  const comparablePreset=(row:Row):ModelInfo|undefined=>{const preset=presetFor(row);return preset?initializeContextLimits(copyInfo(preset)):undefined;};const normalizedInfoPresetDiff=():boolean=>{const row=infoRow();const preset=row?comparablePreset(row):undefined;return!!preset&&!!infoDraft&&!sameJson(infoDraft,preset);};const normalizedInfoFieldDiff=(field:keyof ModelInfo):boolean=>{const row=infoRow();const preset=row?comparablePreset(row):undefined;return!!preset&&!!infoDraft&&!sameJson(infoDraft[field],preset[field]);};
  function applyValidatedInfo():void{const row=infoRow();if(!row||!infoDraft)return;if(infoDraft.auto_compact_token_limit>infoDraft.context_window){error=t('modelInfo.autoCompactExceedsContext');return;}const stringsReady=[infoDraft.slug,infoDraft.display_name,infoDraft.description,String(infoDraft.identity??'')].every((value)=>value.trim());if(!stringsReady||!Number.isInteger(infoDraft.priority)||infoDraft.priority<=0||!Number.isInteger(infoDraft.context_window)||infoDraft.context_window<=0||!Number.isInteger(infoDraft.effective_context_window_percent)||infoDraft.effective_context_window_percent<=0||infoDraft.effective_context_window_percent>100||!Number.isInteger(infoDraft.auto_compact_token_limit)||infoDraft.auto_compact_token_limit<=0||!infoDraft.input_modalities.length||!reasoningValues(infoDraft).length){error=t('modelInfo.completeRequired');return;}if(contextPresets(infoDraft).length)infoDraft.context_window_presets=orderedContextPresets(infoDraft);const preset=comparablePreset(row);row.info=preset&&sameJson(infoDraft,preset)?null:copyInfo(infoDraft);markModified(row);rows=[...rows];closeInfo();}
  function candidateLabel(candidate:SwitchCandidate):string{return candidate.credential_id?`${candidate.provider} (${candidate.credential_id})`:candidate.provider;}function rateLabel(rate:number|null):string{return rate===null?'—':`${rate}x`;}function notifySwitch(event:SwitchEvent):void{if(!('Notification'in window)||Notification.permission!=='granted')return;try{new Notification(t('notification.modelGroupSwitchTitle',{group:event.group}),{body:t('notification.modelGroupSwitchBody',{old:candidateLabel(event.old_candidate),next:candidateLabel(event.new_candidate),oldRate:rateLabel(event.old_rate),newRate:rateLabel(event.new_rate)})});}catch{/* System notification delivery is best-effort. */}}
  $effect(()=>{if(infoDraft&&(!Number.isInteger(infoDraft.effective_context_window_percent)||!Number.isInteger(infoDraft.auto_compact_token_limit)))infoDraft=initializeContextLimits(infoDraft);});
  onMount(()=>{reset();const controller=new AbortController();let cursor:number|null=null;let polling=false;const poll=async():Promise<void>=>{if(polling||controller.signal.aborted)return;polling=true;const requestedCursor=cursor;try{const suffix=requestedCursor===null?'':`?cursor=${requestedCursor}`;const result=await api.get<SwitchEventResponse>(`/admin/api/model-group-switch-events${suffix}`,controller.signal);if(requestedCursor===cursor||cursor===null){cursor=Math.max(cursor??0,result.cursor);for(const event of result.events)notifySwitch(event);}}catch(cause){if(!(cause instanceof DOMException&&cause.name==='AbortError')){/* Polling is non-blocking. */}}finally{polling=false;}};void load(controller.signal);void poll();const pollTimer=window.setInterval(()=>void poll(),2000);return()=>{controller.abort();window.clearInterval(pollTimer);};});
</script>
<div class="section"><div class="section-header"><h2>{t('section.codexTaskModels')}</h2></div><div class="codex-task-model-grid"><div class="codex-task-model-field"><label for="autoReviewModel">{t('label.autoApprovalModel')}</label><Dropdown id="autoReviewModel" value={reviewModel} options={modelOptions('codex-auto-review',reviewModel)} fitViewport={true} onChange={(value:DropdownValue)=>{reviewModel=String(value);void saveTaskModels();}} /></div><div class="codex-task-model-field"><label for="memoryConsolidationModel">{t('label.memoryConsolidationModel')}</label><Dropdown id="memoryConsolidationModel" value={consolidationModel} options={modelOptions('gpt-5.4',consolidationModel)} fitViewport={true} onChange={(value:DropdownValue)=>{consolidationModel=String(value);void saveTaskModels();}} /></div><div class="codex-task-model-field"><label for="memoryExtractModel">{t('label.memoryExtractModel')}</label><Dropdown id="memoryExtractModel" value={extractModel} options={modelOptions('gpt-5.4-mini',extractModel)} fitViewport={true} onChange={(value:DropdownValue)=>{extractModel=String(value);void saveTaskModels();}} /></div></div></div>
<div class="section"><div class="section-header"><h2>{t('section.models')}</h2><div style="display:flex;gap:6px"><button class="btn btn-sm" onclick={()=>void requestNotificationPermission(true)}>{t('btn.requestNotificationPermission')}</button><button class="btn btn-sm" onclick={openFetch}>{t('btn.fetchModels')}</button><button class="btn btn-sm" onclick={openNew}>{t('btn.addModelGroup')}</button></div></div>{#if error}<div class="toast error show" role="alert">{error}</div>{/if}{#if notice}<div class="toast show" role="status">{notice}</div>{/if}<div class="model-toolbar"><Dropdown ariaLabel={t('aria.providerFilter')} value={providerFilter} options={[{value:'',label:t('filter.allProviders')},...Object.keys(config.providers??{}).map((item)=>({value:item,label:item}))]} fitViewport={true} onChange={(value:DropdownValue)=>{providerFilter=String(value);}} /><input aria-label={t('aria.searchModels')} bind:value={search} placeholder={t('placeholder.searchModels')} /><span class="model-count">{t('format.modelCount',{count:Object.keys(config.models??{}).length})}</span></div>
{#if loading}<p style="color:var(--text-dim)">{t('loading.modelGroups')}</p>{:else}<div class="model-group-list">{#each Object.entries(config.model_groups??{}) as [groupName,group]}{#if visibleGroup(groupName,group)}{@const groupProviderNames=providerNames(group)}<div class="model-group-card" class:collapsed={collapsed.has(groupName)} class:config-error={!!group.validation_error}><div class="model-group-head"><div class="model-group-title"><button class="key-btn model-group-toggle" aria-label={t('aria.toggleGroup')} onclick={()=>toggleGroup(groupName)}>{collapsed.has(groupName)?'▸':'▾'}</button><code>{groupName}</code>{#if group.validation_error}<span class="badge badge-error" title={group.validation_error}>{t('model.configError')}</span>{/if}<span class="model-group-meta">{[(group.type??'llm')==='llm'?t('label.llm'):group.type,groupProviderNames.join(' → '),...(group.tool_profile?[group.tool_profile]:[]),`${Object.keys(group.models??{}).length}`].join(' · ')}</span></div><div class="model-group-actions"><button class="btn btn-sm" onclick={()=>edit(groupName,group)}>{t('btn.edit')}</button><button class="btn btn-sm btn-danger" disabled={busy} onclick={()=>void remove(groupName)}>{t('btn.delete')}</button></div></div><div class="model-group-body"><div class="table-scroll"><table><tbody>{#each Object.entries(group.models??{}) as [modelName,entry]}<tr style:opacity={config.providers?.[group.provider??groupProviderNames[0]??'']?.enabled===false?0.4:1}><td><code>{modelName}</code>{#if entry.upstream_model}<span style="font-size:11px;color:var(--text-dim)"> → {entry.upstream_model}</span>{/if}{#each entry.model_info?.input_modalities??[] as modality}<span class="badge badge-cap">{t(`modelInfo.modality.${modality}`)}</span>{/each}</td><td>{groupProviderNames.join(' → ')}</td><td style="text-align:right"><ModelTestPanel model={modelName}/></td></tr>{/each}</tbody></table></div></div></div>{/if}{:else}<div style="color:var(--text-dim);font-size:13px">{t('empty.modelGroups')}</div>{/each}</div>{/if}</div>

<Modal open={groupOpen} labelledby="model-group-title" className="model-group-modal" wide onclose={()=>{groupOpen=false;closeEditors();}}>
  {#snippet header()}<h3 id="model-group-title">{originalName?t('modal.editModelGroup'):t('modal.addModelGroup')}</h3>{/snippet}
  {#snippet children()}
    <div class="form-group"><label for="modelGroupName">{t('label.modelGroupName')}</label><input id="modelGroupName" bind:value={name} placeholder={t('placeholder.modelGroupName')} /></div>
    <div class="form-group">
      <div class="form-label">{t('label.modelGroupProviders')}</div>
      <div class="table-scroll model-group-provider-table">
        <SortableTableEnhanced items={providerRows} currentId={currentProviderRowId} disabled={busy} verticalSeparators={true} onReorder={reorderProviders} onRemove={removeProviderRow} onCurrentChange={selectCurrentProviderRow} getRowColorPreset={providerRowColor} getCurrentLabel={(row)=>t('aria.currentModelGroupProvider',{provider:row.name})} getDragLabel={(row)=>t('aria.dragModelGroupProvider',{provider:row.name})} getRemoveLabel={(row)=>t('aria.removeModelGroupProvider',{provider:row.name})}>
          {#snippet header()}<th>{t('col.provider')}</th><th>{t('col.status')}</th><th>{t('col.error')}</th>{/snippet}
          {#snippet children(row)}<td>{#if row.name&&row.auto_rotate_credentials===false}<div class="model-group-provider-pair"><Dropdown className="model-group-provider-select" ariaLabel={t('label.selectProvider')} value={row.name} options={[{value:'',label:t('label.selectProvider')},...providerOptions(row).map((item)=>({value:item,label:item}))]} fitViewport={true} menuAlign="left" portal={true} onChange={(value:DropdownValue)=>selectProviderRow(row,String(value))} /><Dropdown className="model-group-provider-select" ariaLabel={t('label.selectCredential')} value={row.credential_uuid??''} options={[{value:'',label:t('label.selectCredential')},...credentialOptions(row).map((item)=>({value:item.uuid,label:item.id}))]} fitViewport={true} menuAlign="left" portal={true} onChange={(value:DropdownValue)=>selectCredentialRow(row,String(value))} /></div>{:else}<Dropdown className="model-group-provider-select" ariaLabel={t('label.selectProvider')} value={row.name} options={[{value:'',label:t('label.selectProvider')},...providerOptions(row).map((item)=>({value:item,label:item}))]} fitViewport={true} menuAlign="left" portal={true} onChange={(value:DropdownValue)=>selectProviderRow(row,String(value))} />{/if}</td><td class="model-group-provider-status">{#if row.name}<span class:available={row.status==='available'&&!row.error} class:cooling={row.status==='cooling'&&!row.error} class:disabled={row.status==='disabled'||!!row.error}>{t(`modelGroup.provider.${row.status}`)}</span>{/if}</td><td class="model-group-provider-error">{row.error??''}</td>{/snippet}
        </SortableTableEnhanced>
      </div>
      <button type="button" class="btn btn-sm" onclick={addProviderRow}>{t('btn.addProvider')}</button>
    </div>
    <div class="form-group model-group-dropdown-field"><label for="modelGroupToolProfile">{t('tools.profile')}</label><Dropdown id="modelGroupToolProfile" value={toolProfile} disabled={!passthroughOption&&!compatibleToolProfiles.length} options={[{value:'',label:t('model.providerDefault')},...(passthroughOption?[{value:passthroughOption.id,label:t('tools.passThrough')}]:[]),...compatibleToolProfiles.map((profile)=>({value:profile.id,label:profile.name}))]} fitViewport={true} fitContent={true} portal={true} onChange={(value:DropdownValue)=>{toolProfile=String(value);}} /></div>
    <div class="form-group"><div class="form-label">{t('label.modelMappings')}</div><div>{#each rows as row(row.id)}{@const status=infoStatus(row)}<div class="model-group-row"><input aria-label={t('aria.exposedModel')} bind:value={row.name} placeholder={t('placeholder.exposedModel')} /><input aria-label={t('aria.upstreamModel')} bind:value={row.upstream} placeholder={t('placeholder.upstreamModel')} /><div><div class="model-preset-status" class:detected={status.detected} class:modified={status.modified}>{status.text}</div><div class="model-row-controls"><button class="btn btn-sm" onclick={()=>editInfo(row)}>{t('modelInfo.manual')}</button>{#if hasProviderExtraConfig(row)}<button class="btn btn-sm" onclick={()=>editLimits(row)}>{t('modelInfo.providerLimits',{provider:providerDisplayName()})}</button>{/if}<button class="btn btn-sm btn-danger" onclick={()=>removeRow(row.id)}>{t('btn.remove')}</button></div></div></div>{/each}</div><button class="btn btn-sm" onclick={()=>addRow()}>{t('btn.addMapping')}</button></div>
  {/snippet}
  {#snippet actions()}<button class="btn" onclick={()=>{groupOpen=false;closeEditors();}}>{t('btn.cancel')}</button><button class="btn btn-primary" disabled={busy||!providersComplete()} onclick={()=>void save()}>{t('btn.save')}</button>{/snippet}
  {#snippet sidecar()}
    <div class="modal model-info-modal" class:open={infoRowId!==null&&infoDraft!==null} role="dialog" aria-modal="true" aria-labelledby="model-info-title">
      {#if infoDraft}
        <div class="modal-header"><h3 id="model-info-title">{t('modelInfo.title')}</h3></div>
        <div class="modal-body">
          <div class="model-info-grid">
            <div class="form-group span-2"><label for="modelInfoSlug">{t('modelInfo.slug')}</label><input id="modelInfoSlug" class:model-info-field-modified={infoFieldDiff('slug')} bind:value={infoDraft.slug}/></div>
            <div class="form-group"><label for="modelInfoDisplayName">{t('modelInfo.displayName')}</label><input id="modelInfoDisplayName" class:model-info-field-modified={infoFieldDiff('display_name')} bind:value={infoDraft.display_name}/></div>
            <div class="form-group"><label for="modelInfoIdentity">{t('modelInfo.identity')}</label><input id="modelInfoIdentity" class:model-info-field-modified={infoFieldDiff('identity')} bind:value={infoDraft.identity}/></div>
            <div class="form-group span-2"><label for="modelInfoDescription">{t('modelInfo.description')}</label><textarea id="modelInfoDescription" class:model-info-field-modified={infoFieldDiff('description')} bind:value={infoDraft.description}></textarea></div>
            <div class="form-group"><label for="modelInfoPriority">{t('modelInfo.priority')}</label><input id="modelInfoPriority" class:model-info-field-modified={infoFieldDiff('priority')} type="number" min="1" bind:value={infoDraft.priority}/></div>
            <div class="form-group"><div class="form-label">{t('modelInfo.modalities')}</div><div class="checkbox-group model-info-checkbox-group" class:model-info-field-modified={infoFieldDiff('input_modalities')}>{#each modalityOptions as value}<label><input type="checkbox" checked={infoDraft.input_modalities.includes(value)} onchange={(event)=>toggleList('input_modalities',value,event.currentTarget.checked)}/>{t(`modelInfo.modality.${value}`)}</label>{/each}</div></div>
            <div class="form-group span-2"><label for="modelInfoContextWindow">{t('modelInfo.contextWindow')}</label><div class="context-window-controls" class:model-info-field-modified={infoFieldDiff('context_window')}><Dropdown id="modelInfoContextWindowPreset" ariaLabel={t('modelInfo.contextWindow')} value={contextWindowSelection()} options={contextWindowOptions()} onChange={selectContextWindow}/><input id="modelInfoContextWindow" type="number" min="1" bind:value={infoDraft.context_window}/></div></div>
            <div class="form-group"><label for="modelInfoEffectiveContextWindowPercent">{t('modelInfo.effectiveContextWindowPercent')}</label><input id="modelInfoEffectiveContextWindowPercent" class:model-info-field-modified={normalizedInfoFieldDiff('effective_context_window_percent')} type="number" min="1" max="100" bind:value={infoDraft.effective_context_window_percent}/></div>
            <div class="form-group"><label for="modelInfoAutoCompactTokenLimit">{t('modelInfo.autoCompactTokenLimit')}</label><input id="modelInfoAutoCompactTokenLimit" class:model-info-field-modified={normalizedInfoFieldDiff('auto_compact_token_limit')} type="number" min="1" bind:value={infoDraft.auto_compact_token_limit}/></div>
            <div class="form-group span-2"><div class="form-label">{t('modelInfo.reasoningLevels')}</div><div class="checkbox-group model-info-checkbox-group" class:model-info-field-modified={infoFieldDiff('supported_reasoning_levels')}>{#each reasoningOptions as value}<label><input type="checkbox" checked={reasoningValues(infoDraft).includes(value)} onchange={(event)=>toggleList('supported_reasoning_levels',value,event.currentTarget.checked)}/>{t(`modelInfo.reasoning.${value}`)}</label>{/each}</div></div>
          </div>
        </div>
        <div class="modal-actions"><button class="btn" type="button" disabled={!!(infoRow()&&presetFor(infoRow()!))&&!normalizedInfoPresetDiff()} onclick={clearInfo}>{#if infoRow()&&presetFor(infoRow()!)}{t('modelInfo.restorePreset',{display_name:presetFor(infoRow()!)!.display_name})}{:else}{t('modelInfo.useAutomatic')}{/if}</button><button class="btn" type="button" onclick={closeInfo}>{t('btn.cancel')}</button><button class="btn btn-primary" type="button" onclick={applyValidatedInfo}>{t('btn.applyChanges')}</button></div>
      {/if}
    </div>
    <div class="modal model-info-modal" class:open={limitRowId!==null&&runtimeFields().length>0} role="dialog" aria-modal="true" aria-labelledby="provider-limits-title">
      {#if limitRowId!==null}
        <div class="modal-header"><h3 id="provider-limits-title">{t('modelInfo.providerLimitsTitle',{provider:providerDisplayName()})}</h3></div>
        <div class="modal-body">
          <p class="field-hint provider-limit-hint">{t('modelInfo.providerLimitsHint')}</p>
          {#each runtimeFields() as field}
            <div class="provider-limit-row">
              <label class="provider-limit-toggle"><input type="checkbox" checked={Object.hasOwn(runtimeDraft,field)} onchange={(event)=>toggleRuntime(field,event.currentTarget.checked)}/><span>{field}</span></label>
              <input aria-label={field} type="number" min="0" max={field==='temperature'?2:1} step="0.01" disabled={!Object.hasOwn(runtimeDraft,field)} value={runtimeDraft[field]??''} oninput={(event)=>setRuntime(field,event.currentTarget.value===''?null:event.currentTarget.valueAsNumber)}/>
            </div>
          {/each}
        </div>
        <div class="modal-actions"><button class="btn" type="button" onclick={clearLimits}>{t('modelInfo.clearProviderLimits')}</button><button class="btn" type="button" onclick={closeLimits}>{t('btn.cancel')}</button><button class="btn btn-primary" type="button" onclick={applyLimits}>{t('btn.applyChanges')}</button></div>
      {/if}
    </div>
  {/snippet}
</Modal>
<Modal open={fetchOpen} labelledby="fetch-models-title" wide onclose={()=>fetchOpen=false}>{#snippet header()}<h3 id="fetch-models-title">{t('modal.fetchModels')}</h3>{/snippet}<div class="form-group"><label for="fetchProvider">{t('label.selectProvider')}</label><Dropdown id="fetchProvider" value={provider} options={Object.keys(config.providers??{}).map((item)=>({value:item,label:item}))} onChange={(value:DropdownValue)=>{provider=String(value);}} /></div><div class="form-group"><label for="fetchGroupName">{t('label.modelGroupName')}</label><input id="fetchGroupName" bind:value={name} placeholder={t('placeholder.fetchGroupName')} /></div>{#if discovered.length}<div class="fetch-toolbar"><input bind:value={discoveryFilter} placeholder={t('placeholder.filterModels')}/><button class="btn btn-sm" onclick={()=>selectedDiscovered=new Set(filteredDiscovered)}>{t('btn.selectAll')}</button><button class="btn btn-sm" onclick={()=>selectedDiscovered=new Set()}>{t('btn.deselectAll')}</button><span class="fetch-count">{t('format.selected',{count:selectedDiscovered.size})}</span></div><div class="fetch-models-list">{#each filteredDiscovered as model}<label><input type="checkbox" checked={selectedDiscovered.has(model)} onchange={(event)=>selectModel(model,event.currentTarget.checked)}/>{model}</label>{/each}</div><div class="prefix-group"><label for="fetchPrefix">{t('label.modelPrefix')}</label><input id="fetchPrefix" bind:value={prefix} placeholder={t('placeholder.modelPrefix')}/></div>{/if}{#snippet actions()}<button class="btn" onclick={()=>fetchOpen=false}>{t('btn.cancel')}</button>{#if !discovered.length}<button class="btn btn-primary" disabled={busy||!provider} onclick={()=>void discover()}>{t('btn.fetch')}</button>{:else}<button class="btn btn-primary" disabled={!selectedDiscovered.size||!name.trim()} onclick={addSelected}>{t('btn.applyChanges')}</button>{/if}{/snippet}</Modal>

<style>
  :global(.modal.model-group-modal) { width: 880px; max-width: 80vw; max-height: 80vh; }
  .model-group-provider-pair{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:6px}
</style>
